import {icon,cast,state} from './app.js?v=8';
const $=s=>document.querySelector(s);
const gameIds=new Set([1,2,3,5,6,7,8]);
let generation=0,timers=[];
export const isMiniGame=i=>gameIds.has(i);
export function cleanupMiniGame(){generation++;timers.forEach(clearTimeout);timers=[]}
const later=(fn,ms)=>{const token=generation;timers.push(setTimeout(()=>{if(token===generation)fn()},ms))};
const quiet=()=>state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;
const pad=()=>`<div class="mini-pad" aria-label="Movement controls"><button data-move="up" aria-label="Move up">↑</button><button data-move="left" aria-label="Move left">←</button><button data-move="down" aria-label="Move down">↓</button><button data-move="right" aria-label="Move right">→</button></div>`;
const footer=()=>`<div class="mini-footer"><p id="mini-status" role="status">Play to complete the goal. There is no timer.</p><button id="mini-help" class="text-btn">Science hint</button></div>`;
export function renderMiniGame(i){
 let html='';
 if(i===1)html=`<div class="leaf-engine"><div class="engine-sky"><span class="engine-sun">${cast('sun')}</span><span class="engine-cloud" aria-hidden="true"></span></div><div class="engine-core">${cast('sprout')}<div id="engine-stores" class="engine-stores" aria-label="Stored food"></div></div><div class="engine-controls"><button id="engine-water" class="mini-control">${icon('drop')} Pump water <b id="water-reserve">0</b></button><button id="engine-co2" class="mini-control">CO₂ valve <b id="co2-reserve">0</b></button><button id="engine-green" class="mini-control" aria-pressed="false">${icon('leaf')} Chlorophyll: off</button><label class="mini-control engine-light">${icon('sun')} Clear the cloud<input id="engine-light" type="range" min="0" max="100" value="0" step="10" aria-label="Uncover the Sun"><span id="engine-light-label">Sun covered</span></label></div><button id="engine-run" class="btn yellow">${icon('play')} Run the leaf</button><p class="mini-goal" id="engine-goal">Store 3 batches of food · 0 / 3</p></div>`;
 if(i===2)html=`<div class="mini-mirror"><p class="mini-goal">Turn the two game mirrors. Guide the Sun’s beam into the leaf.</p><div id="mirror-board" class="mirror-board"><svg id="mirror-beam" viewBox="0 0 500 500" aria-hidden="true"><polyline id="beam-path" points=""/></svg><div id="mirror-cells"></div></div></div>`;
 if(i===3||i===5)html=`<div class="mini-grid-layout"><div><p class="mini-goal">${i===3?'Steer the blue water drop to ROOTS. Stone walls block the way.':'Push both G (glucose) crates into the storage spots. They become S (starch).'}</p><div id="mini-grid" class="mini-grid ${i===3?'water-maze':'starch-store'}" tabindex="0" role="group" aria-label="${i===3?'Water maze':'Glucose storage puzzle'}: use arrow keys or movement buttons"></div></div><div class="mini-side">${i===3?cast('drop'):'<span class="mini-oxygen">O₂ → air</span>'}${pad()}<button id="mini-reset" class="text-btn">Restart this puzzle</button><small>${i===3?'Water is a need. Roots absorb it.':'G = glucose · S = stored starch. Oxygen is released into the air.'}</small></div></div>`;
 if(i===6)html=`<div class="mini-conveyor"><p class="mini-goal" id="belt-goal">Deliver 6 supplies · 0 / 6</p><div class="belt-world"><svg viewBox="0 0 600 300" preserveAspectRatio="none" aria-hidden="true"><path d="M300 0V135L105 270M300 135l195 135"/></svg><div id="belt-cargo" class="belt-cargo"></div><button id="belt-gate" aria-label="Switch the conveyor gate">${icon('arrow')} Gate → NEEDS</button><div class="belt-bin needs-bin"><b>NEEDS</b><span id="needs-delivered">0 delivered</span></div><div class="belt-bin products-bin"><b>PRODUCTS</b><span id="products-delivered">0 delivered</span></div></div><button id="belt-send" class="btn yellow">${icon('play')} Send along the belt</button></div>`;
 if(i===7)html=`<div class="food-rail-layout"><div><p class="mini-goal">Connect the food-energy track: plant → caterpillar → bird.</p><div id="food-rail" class="food-rail" aria-label="Rotate track pieces to connect the food chain"></div></div><div class="mini-side">${cast('sprout')}<button id="rail-run" class="btn yellow">${icon('play')} Send food energy</button><small>Tap a track piece to turn it. The plant makes food; the caterpillar eats the plant; the bird eats the caterpillar.</small></div></div>`;
 if(i===8)html=`<div class="gas-catcher"><div class="catcher-toolbar"><b id="gas-goal">Let 5 CO₂ bubbles into the leaf · 0 / 5</b><button id="gas-pause" class="text-btn">Pause bubbles</button></div><div id="gas-field" class="gas-field"><div class="catcher-leaf">${icon('leaf')}<b>LEAF</b><span id="released-oxygen">O₂ released: 0</span></div>${['CO₂','O₂','CO₂','CO₂','O₂','CO₂','O₂','CO₂'].map((gas,n)=>`<button data-gas="${gas==='CO₂'?'co2':'oxygen'}" class="catch-bubble ${gas==='CO₂'?'co2':'o2'}" style="--x:${[10,34,70,19,80,12,43,83][n]}%;--y:${[13,12,15,49,51,78,75,78][n]}%;--drift:${n%2?'-16px':'16px'};--delay:${-n*.7}s" aria-label="${gas==='CO₂'?'Carbon dioxide':'Oxygen'} bubble">${gas}</button>`).join('')}</div></div>`;
 return `<section class="mini-game" data-mini-game="${i}">${html}${footer()}</section>`;
}
export function bindMiniGame(i,onWin,onHint){
 let won=false;
 const root=$('.mini-game');
 const say=text=>{if($('#mini-status'))$('#mini-status').textContent=text};
 const finish=()=>{if(won)return;won=true;root.classList.add('mini-won');root.querySelectorAll('button,input').forEach(b=>b.disabled=true);say('Goal complete! Your Next button is unlocked.');onWin()};
 $('#mini-help').onclick=()=>{onHint();say({1:'All four needs must be ready: sunlight, water, carbon dioxide and chlorophyll. Running the leaf uses water and carbon dioxide and makes food and oxygen.',2:'The Sun supplies light energy. A slash-shaped game mirror turns the beam around a corner. Aim for the leaf.',3:'Roots absorb water. Move along connected open channels until you reach ROOTS. Hitting a stone does not lose a point.',5:'The leaf makes glucose. It can be combined and stored as starch. Push a G crate by standing behind it. Oxygen is released.',6:'Water and carbon dioxide go to NEEDS. Starch and oxygen go to PRODUCTS.',7:'Photosynthesis makes food in the plant. The caterpillar eats the plant; the bird eats the caterpillar. Connect through the centre caterpillar.',8:'Photosynthesis takes in carbon dioxide and releases oxygen. Let CO₂ into the leaf; leave O₂ in the air. This helps balance gases.'}[i])};
 if(i===1){
  let water=0,co2=0,green=false,light=0,batches=0;
  const draw=()=>{root.style.setProperty('--engine-light',light/100);root.classList.toggle('engine-green',green);root.classList.toggle('engine-clear',light===100);$('#water-reserve').textContent=water;$('#co2-reserve').textContent=co2;$('#engine-green').setAttribute('aria-pressed',green);$('#engine-green').innerHTML=icon('leaf')+' Chlorophyll: '+(green?'on':'off');$('#engine-light-label').textContent=light===100?'Sun uncovered':'Sun covered · '+light+'%';$('#engine-stores').innerHTML=Array.from({length:3},(_,n)=>`<span class="${n<batches?'filled':''}">${n<batches?'S':'·'}</span>`).join('');$('#engine-goal').textContent=`Store 3 batches of food · ${batches} / 3`};
  $('#engine-water').onclick=()=>{water=Math.min(3,water+1);draw();say('Water entered through the roots.')};$('#engine-co2').onclick=()=>{co2=Math.min(3,co2+1);draw();say('Carbon dioxide entered the leaf.')};$('#engine-green').onclick=()=>{green=!green;draw();say(green?'Chlorophyll is ready to absorb light.':'The leaf has no light-catching chlorophyll.')};$('#engine-light').oninput=e=>{light=Number(e.target.value);draw();say(light===100?'Sun uncovered. Chlorophyll can absorb its light energy.':'Move the cloud fully away to uncover the Sun.')};
  $('#engine-run').onclick=()=>{if(won)return;const missing=[!water&&'water',!co2&&'carbon dioxide',!green&&'chlorophyll',light!==100&&'sunlight (fully uncover the Sun)'].filter(Boolean);if(missing.length){say('No new food yet. The leaf still needs '+missing.join(', ')+'.');return}water--;co2--;batches++;draw();say('Glucose made → stored starch. Oxygen released into the air!');if(batches===3)finish()};draw();
 }
 if(i===2){
  const mirrors={7:'\\',17:'\\'};
  const draw=()=>{
   $('#mirror-cells').innerHTML=Array.from({length:25},(_,n)=>n in mirrors?`<button data-mirror="${n}" aria-label="Rotate game mirror ${n===7?'upper':'lower'}">${mirrors[n]}</button>`:`<span class="${n===15?'beam-sun':n===9?'beam-leaf':''}">${n===15?icon('sun'):n===9?icon('leaf'):''}</span>`).join('');
   let x=0,y=3,dx=1,dy=0,points=['50,350'],reached=false;
   for(let k=0;k<30;k++){x+=dx;y+=dy;if(x<0||x>4||y<0||y>4)break;points.push(`${x*100+50},${y*100+50}`);if(x===4&&y===1){reached=true;break}const m=mirrors[y*5+x];if(m){const oldDx=dx;dx=m==='/'?-dy:dy;dy=m==='/'?-oldDx:oldDx}}
   $('#beam-path').setAttribute('points',points.join(' '));
   root.querySelectorAll('[data-mirror]').forEach(b=>b.onclick=()=>{if(won)return;const n=b.dataset.mirror;mirrors[n]=mirrors[n]==='/'?'\\':'/';draw()});if(reached){say('Sunlight reached the leaf, where chlorophyll absorbs its energy.');finish()}
  };draw();
 }
 if(i===3||i===5){
  const width=i===3?5:6,height=5,initial=i===3?20:13;let player=initial,crates=new Set([14,15]);
  const open=new Set([20,15,10,11,12,7,2,3,4,16,17,5,1,8,13,18]);const goals=new Set([8,9]);
  const wall=n=>n<0||n>=width*height||(i===3?!open.has(n):n%width===0||n%width===5||Math.floor(n/width)===0||Math.floor(n/width)===4);
  const draw=()=>{$('#mini-grid').style.setProperty('--columns',width);$('#mini-grid').innerHTML=Array.from({length:width*height},(_,n)=>`<span class="grid-square ${wall(n)?'stone':''} ${i===3&&n===4?'root-goal':''} ${i===5&&goals.has(n)?'storage-goal':''} ${i===5&&crates.has(n)?'food-crate':''} ${n===player?'player':''}">${n===player?(i===3?icon('drop'):icon('flag')):i===3&&n===4?'ROOTS':i===5&&crates.has(n)?(goals.has(n)?'S':'G'):i===5&&goals.has(n)?'STORE':''}</span>`).join('')};
  const move=direction=>{if(won)return;const delta={up:-width,down:width,left:-1,right:1}[direction],next=player+delta;if(wall(next)||Math.abs(next%width-player%width)>1){say('A wall blocks that way. Try another route.');return}if(i===5&&crates.has(next)){const beyond=next+delta;if(wall(beyond)||crates.has(beyond)){say('The crate needs clear space behind it. Walk around and push from another side.');return}crates.delete(next);crates.add(beyond)}player=next;draw();if(i===3&&player===4)finish();if(i===5&&[...goals].every(n=>crates.has(n)))finish()};
  root.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));root.onkeydown=e=>{const d={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key];if(d){e.preventDefault();move(d)}};$('#mini-reset').onclick=()=>{player=initial;crates=new Set([14,15]);draw();say('Puzzle restarted. Try a new route.')};draw();
 }
 if(i===6){
  const queue=[['Water','needs'],['Oxygen','products'],['Carbon dioxide','needs'],['Starch','products'],['Water','needs'],['Oxygen','products']];let gate='needs',delivered=0,busy=false,counts={needs:0,products:0};
  const draw=()=>{if(delivered<queue.length)$('#belt-cargo').textContent=queue[delivered][0];$('#belt-gate').innerHTML=icon('arrow')+' Gate → '+gate.toUpperCase();$('#belt-gate').classList.toggle('gate-right',gate==='products');$('#belt-goal').textContent=`Deliver 6 supplies · ${delivered} / 6`;for(const key of ['needs','products'])$('#'+key+'-delivered').textContent=counts[key]+' delivered'};
  $('#belt-gate').onclick=()=>{if(busy||won)return;gate=gate==='needs'?'products':'needs';draw()};
  $('#belt-send').onclick=()=>{if(busy||won)return;busy=true;const cargo=$('#belt-cargo'),destination=gate;$('#belt-gate').disabled=true;$('#belt-send').disabled=true;cargo.classList.add('travelling');cargo.style.left=gate==='needs'?'18%':'82%';cargo.style.top='72%';later(()=>{const correct=queue[delivered][1]===destination;if(correct){counts[destination]++;delivered++;say('Delivered! The workshop is working.')}else{say(queue[delivered][0]+' belongs with '+queue[delivered][1]+'. Reverse the gate and try again.');onHint()}cargo.classList.remove('travelling');cargo.style.left='50%';cargo.style.top='9%';busy=false;$('#belt-gate').disabled=false;$('#belt-send').disabled=false;draw();if(delivered===queue.length)finish()},quiet()?0:750)};draw();
 }
 if(i===7){
  const base=[[3,1],[3,2],[0,2],[0,1],[0,2],[0,1],[0,1],[0,1],[3,1]],turns=[0,1,2,3,0,1,3,2,0];let busy=false;
  const ports=n=>base[n].map(d=>(d+turns[n])%4);
  const draw=()=>{$('#food-rail').innerHTML=base.map((_,n)=>{const p=ports(n),xy=[[50,0],[100,50],[50,100],[0,50]];return `<button data-rail="${n}" ${[0,4,8].includes(n)?'disabled':''} aria-label="${n===0?'Food starts in plant':n===4?'Caterpillar eats plant':n===8?'Bird eats caterpillar':'Rotate food track row '+(Math.floor(n/3)+1)+', column '+(n%3+1)}"><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M${xy[p[0]].join(' ')}L50 50L${xy[p[1]].join(' ')}"/></svg>${[0,4,8].includes(n)?`<b>${n===0?'PLANT':n===4?'CATERPILLAR':'BIRD'}</b>`:''}</button>`}).join('');root.querySelectorAll('[data-rail]').forEach(b=>b.onclick=()=>{if(busy||won)return;turns[Number(b.dataset.rail)]++;draw()})};
  $('#rail-run').onclick=()=>{if(busy||won)return;root.querySelectorAll('.energy-flow').forEach(e=>e.classList.remove('energy-flow'));let n=0,entry=3,seen=[],ok=false;for(let k=0;k<10;k++){if(seen.includes(n)||!ports(n).includes(entry))break;seen.push(n);const exit=ports(n).find(d=>d!==entry);if(n===8&&exit===1){ok=seen.includes(4);break}const r=Math.floor(n/3)+[-1,0,1,0][exit],c=n%3+[0,1,0,-1][exit];if(r<0||r>2||c<0||c>2)break;n=r*3+c;entry=(exit+2)%4}busy=true;$('#rail-run').disabled=true;seen.forEach((cell,k)=>later(()=>root.querySelector(`[data-rail="${cell}"]`)?.classList.add('energy-flow'),quiet()?0:k*180));later(()=>{busy=false;$('#rail-run').disabled=false;if(ok)finish();else say('The food-energy packet stopped. Turn a track to carry it through the caterpillar to the bird.')},quiet()?0:Math.max(1,seen.length)*180)};draw();
 }
 if(i===8){
  let caught=0,paused=false;
  $('#gas-pause').onclick=()=>{paused=!paused;$('#gas-field').classList.toggle('bubbles-paused',paused);$('#gas-pause').textContent=paused?'Resume bubbles':'Pause bubbles'};
  root.querySelectorAll('[data-gas]').forEach(b=>b.onclick=()=>{if(won||b.hidden)return;if(b.dataset.gas==='oxygen'){say('Oxygen is a product released into the air during photosynthesis. Let CO₂ enter the leaf.');onHint();b.classList.add('wrong-gas');return}b.hidden=true;caught++;$('#gas-goal').textContent=`Let 5 CO₂ bubbles into the leaf · ${caught} / 5`;$('#released-oxygen').textContent='O₂ released: '+caught;say('Carbon dioxide entered. The leaf released oxygen into the air.');if(caught===5)finish()});
 }
}
